    {"name": "y", "dir": "input", "width": 3, "description": "Present state"},
    {"name": "Y0", "dir": "output", "width": 1, "description": "Bit 0 of next state Y[2:0]"},
    {"name": "z", "dir": "output", "width": 1, "description": "Moore output based on present state"}
  ],
